  digitsum: { icon: '✅', name: 'இலக்கக் கூட்டல் சரிபார்ப்பு', sample: '47 × 23 = 1081 ✓', tagline: 'எந்தப் பெருக்கலையும் சில நொடிகளில் சரிபாருங்கள்.',
    how: ['ஒரே இலக்கம் வரும் வரை எண்ணின் இலக்கங்களை மீண்டும் மீண்டும் கூட்டுங்கள் (சரிபார்ப்பில் 9 என்பது 0).', 'இரண்டு எண்களின் இலக்கக் கூட்டல்களைப் பெருக்கி, மீண்டும் ஒரே இலக்கமாக்குங்கள்.', 'விடையின் இலக்கக் கூட்டலுடன் ஒப்பிடுங்கள். வேறு என்றால் விடை தவறு.'],
    why: 'ஒரு எண்ணும் அதன் இலக்கக் கூட்டலும் 9 ஆல் வகுக்கும்போது ஒரே மீதி தருகின்றன, மீதிகள் பெருக்கலுக்கும் பொருந்தும்.',
    q: '{n} இன் இலக்கக் கூட்டல் எவ்வளவு?', q_check: '{a} × {b} = {c} சரியா?',
    steps: { start: '{n} இன் இலக்கக் கூட்டலைக் காணுங்கள்.', sum: '{label}: {list} = {s}.', single: '{n} ஏற்கனவே ஒரே இலக்கம்.', root: '{n} இன் இலக்கக் கூட்டல் = {r}.', check: '{a} × {b} = {c} ஐச் சரிபாருங்கள்.', roots: 'இலக்கக் கூட்டல்கள்: {a} → {ra}, {b} → {rb}.', mulroot: '{ra} × {rb} = {prod} → {rm}.', croot: '{c} இன் இலக்கக் கூட்டல் → {rc}.', match: '{rm} = {rc}: விடை பெரும்பாலும் சரி ✓', mismatch: '{rm} ≠ {rc}: {a} × {b} = {c} தவறு ✗' } }
